create extension if not exists pgcrypto;
create table public.sources(id uuid primary key default gen_random_uuid(),name text not null,country text not null,base_url text,type text not null check(type in('API','RSS','ATS','HTML','SEARCH','EMAIL','MANUAL')),priority text not null default 'B' check(priority in('S','A','B','C')),enabled boolean not null default true,adapter_name text,capabilities jsonb not null default '{}',terms_checked boolean not null default false,robots_checked boolean not null default false,last_run_at timestamptz,last_success_at timestamptz,next_run_at timestamptz,health_score int not null default 0 check(health_score between 0 and 100),yield_score numeric not null default 0,unique(name,country));
create table public.users(id uuid primary key references auth.users(id) on delete cascade,timezone text not null default 'Europe/Zagreb',created_at timestamptz not null default now());
create table public.source_checkpoints(id uuid primary key default gen_random_uuid(),source_id uuid not null references public.sources on delete cascade,country text not null,last_started_at timestamptz,last_success_at timestamptz,last_seen_published_at timestamptz,last_external_id text,last_external_cursor text,items_seen int not null default 0,items_new int not null default 0,items_updated int not null default 0,next_run_at timestamptz,status text not null default 'IDLE',error_count int not null default 0,last_error text,unique(source_id,country));
create table public.search_runs(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,trigger_type text not null,status text not null check(status in('QUEUED','RUNNING','PARTIAL_SUCCESS','SUCCESS','FAILED','AUDIT_FAILED','CANCELLED')),started_at timestamptz,finished_at timestamptz,items_seen int not null default 0,items_new int not null default 0,items_updated int not null default 0,errors_count int not null default 0,audit_status text,created_at timestamptz not null default now());
create table public.search_run_sources(id uuid primary key default gen_random_uuid(),search_run_id uuid not null references public.search_runs on delete cascade,source_id uuid not null references public.sources,status text not null,items_seen int not null default 0,error text,unique(search_run_id,source_id));
create table public.raw_ingest(id uuid primary key default gen_random_uuid(),source_id uuid not null references public.sources,search_run_id uuid not null references public.search_runs on delete cascade,external_id text,retrieved_at timestamptz not null default now(),raw_payload jsonb not null,content_hash text not null,processing_status text not null,unique(source_id,external_id,content_hash));
create table public.companies(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,name text not null,canonical_name text not null,domain text,country text,relationship_score int not null default 0,created_at timestamptz not null default now(),unique(user_id,canonical_name));
create table public.company_aliases(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies on delete cascade,alias text not null,unique(company_id,alias));
create table public.company_signals(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies on delete cascade,signal_type text not null,summary text not null,observed_at timestamptz not null,source_url text);
create table public.contacts(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,company_id uuid references public.companies,first_name text,last_name text,email text,role text,do_not_contact boolean not null default false);
create table public.relationships(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,contact_id uuid not null references public.contacts on delete cascade,relationship_score int not null default 0,status text not null,notes text);
create table public.job_postings(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,company_id uuid not null references public.companies,title text not null,canonical_key text not null,location text,country text,freshness text,eligibility text,content_hash text not null,first_seen_at timestamptz not null default now(),last_verified_at timestamptz,expires_at timestamptz,unique(user_id,canonical_key));
create table public.job_sources(id uuid primary key default gen_random_uuid(),job_posting_id uuid not null references public.job_postings on delete cascade,source_id uuid not null references public.sources,external_id text,source_url text not null,unique(job_posting_id,source_id,external_id));
create table public.job_snapshots(id uuid primary key default gen_random_uuid(),job_posting_id uuid not null references public.job_postings on delete cascade,captured_at timestamptz not null default now(),title text not null,description text,requirements jsonb not null default '[]',salary_min numeric,salary_max numeric,currency text,location text,remote_policy text,contract_type text,application_url text,source_url text,valid_until timestamptz,content_hash text not null,unique(job_posting_id,content_hash));
create table public.job_requirements(id uuid primary key default gen_random_uuid(),job_posting_id uuid not null references public.job_postings on delete cascade,requirement text not null,match_status text not null default 'UNKNOWN');
create table public.job_skills(id uuid primary key default gen_random_uuid(),job_posting_id uuid not null references public.job_postings on delete cascade,skill text not null,weight numeric not null default 1,unique(job_posting_id,skill));
create table public.opportunities(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,job_posting_id uuid references public.job_postings,type text not null,potential_min numeric,potential_max numeric,currency text not null default 'EUR',skill_score numeric not null default 0,money_score numeric not null default 0,probability_score numeric not null default 0,urgency_score numeric not null default 0,relationship_score numeric not null default 0,estimated_hours numeric not null check(estimated_hours>0),total_score numeric not null default 0,expected_value numeric not null default 0,expected_value_per_hour numeric not null default 0,status text not null,discovered_at timestamptz not null default now(),expires_at timestamptz,next_action text,next_action_at timestamptz);
create table public.career_facts(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,fact text not null,evidence text,verified boolean not null default false);
create table public.cv_versions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,category text not null,version int not null,content_hash text not null,storage_path text,created_at timestamptz not null default now(),unique(user_id,category,version));
create table public.applications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,opportunity_id uuid not null references public.opportunities,job_snapshot_id uuid not null references public.job_snapshots,cv_version_id uuid not null references public.cv_versions,cover_letter text,submitted_at timestamptz,status text not null,follow_up_at timestamptz);
create table public.application_answers(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications on delete cascade,question text not null,answer text not null);
create table public.cover_letters(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,application_id uuid references public.applications,content text not null,content_hash text not null);
create table public.email_threads(id text primary key,user_id uuid not null references public.users on delete cascade,company_id uuid references public.companies,subject text,lifecycle text,priority int,relationship_score int,next_action text,next_action_at timestamptz,created_at timestamptz not null default now());
create table public.email_messages(id text primary key,thread_id text not null references public.email_threads on delete cascade,sent_at timestamptz not null,direction text not null,from_address text,to_addresses text[] not null,body_ciphertext text,metadata jsonb not null default '{}');
create table public.email_events(id uuid primary key default gen_random_uuid(),thread_id text not null references public.email_threads on delete cascade,event_type text not null,occurred_at timestamptz not null,payload jsonb not null default '{}');
create table public.email_analysis(id uuid primary key default gen_random_uuid(),thread_id text not null references public.email_threads on delete cascade,classification text not null,confidence numeric not null,evidence jsonb not null default '[]',created_at timestamptz not null default now());
create table public.conversation_audits(id uuid primary key default gen_random_uuid(),thread_id text not null references public.email_threads on delete cascade,audit_version text not null,summary text not null,lifecycle_status text not null,relationship_score int not null,findings jsonb not null default '[]',next_action jsonb not null,ethical_risk boolean not null default false,confidence numeric not null,created_at timestamptz not null default now());
create table public.followups(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,opportunity_id uuid references public.opportunities,thread_id text references public.email_threads,due_at timestamptz not null,status text not null,message_angle text);
create table public.referrals(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,from_contact_id uuid references public.contacts,to_company_id uuid references public.companies,opportunity_id uuid references public.opportunities,status text not null,created_at timestamptz not null default now());
create table public.interviews(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,application_id uuid not null references public.applications,scheduled_at timestamptz not null,status text not null,notes text);
create table public.offers(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,application_id uuid not null references public.applications,amount numeric,currency text,status text not null,received_at timestamptz not null);
create table public.revenues(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,opportunity_id uuid references public.opportunities,amount numeric not null,currency text not null,received_at timestamptz not null);
create table public.bounty_programs(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,platform text not null,program text not null,url text not null,min_reward numeric,max_reward numeric,safe_harbor boolean not null default false,status text not null,authorized_scope text not null default 'UNKNOWN' check(authorized_scope in('YES','NO','UNKNOWN')));
create table public.bounty_scopes(id uuid primary key default gen_random_uuid(),program_id uuid not null references public.bounty_programs on delete cascade,asset text not null,in_scope boolean not null,rules text,verified_at timestamptz);
create table public.bounty_findings(id uuid primary key default gen_random_uuid(),program_id uuid not null references public.bounty_programs on delete cascade,title text not null,status text not null,research_minutes int not null default 0,payout numeric);
create table public.tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,title text not null,status text not null,due_at timestamptz,opportunity_id uuid references public.opportunities);
create table public.activity_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,event_type text not null,entity_type text not null,entity_id text not null,payload jsonb not null default '{}',created_at timestamptz not null default now());
create table public.audit_runs(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,status text not null,started_at timestamptz not null default now(),finished_at timestamptz);
create table public.audit_findings(id uuid primary key default gen_random_uuid(),audit_run_id uuid not null references public.audit_runs on delete cascade,code text not null,severity text not null,entity_type text,entity_id text,details jsonb not null default '{}');
create table public.source_statistics(id uuid primary key default gen_random_uuid(),source_id uuid not null references public.sources on delete cascade,day date not null,items_seen int not null default 0,items_new int not null default 0,failures int not null default 0,latency_ms int,unique(source_id,day));

create index idx_opportunities_today on public.opportunities(user_id,status,next_action_at,expected_value_per_hour desc);create index idx_jobs_fresh on public.job_postings(user_id,freshness,eligibility,first_seen_at desc);create index idx_threads_action on public.email_threads(user_id,next_action_at);create index idx_raw_run on public.raw_ingest(search_run_id,processing_status);create index idx_events_entity on public.activity_events(user_id,entity_type,entity_id,created_at desc);

do $$ declare t text; begin foreach t in array array['users','search_runs','search_run_sources','raw_ingest','companies','company_aliases','company_signals','contacts','relationships','job_postings','job_sources','job_snapshots','job_requirements','job_skills','opportunities','career_facts','cv_versions','applications','application_answers','cover_letters','email_threads','email_messages','email_events','email_analysis','conversation_audits','followups','referrals','interviews','offers','revenues','bounty_programs','bounty_scopes','bounty_findings','tasks','activity_events','audit_runs','audit_findings'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
alter table public.sources enable row level security;alter table public.source_checkpoints enable row level security;alter table public.source_statistics enable row level security;
create policy sources_read on public.sources for select to authenticated using (true);
create policy own_users on public.users for all to authenticated using ((select auth.uid())=id) with check ((select auth.uid())=id);
do $$ declare t text; begin foreach t in array array['search_runs','companies','contacts','relationships','job_postings','opportunities','career_facts','cv_versions','applications','cover_letters','email_threads','followups','referrals','interviews','offers','revenues','bounty_programs','tasks','activity_events','audit_runs'] loop execute format('create policy own_rows on public.%I for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id)',t); end loop; end $$;
revoke all on all tables in schema public from anon;grant select on public.sources to authenticated;grant select,insert,update,delete on public.users,public.search_runs,public.companies,public.contacts,public.relationships,public.job_postings,public.opportunities,public.career_facts,public.cv_versions,public.applications,public.cover_letters,public.email_threads,public.followups,public.referrals,public.interviews,public.offers,public.revenues,public.bounty_programs,public.tasks,public.activity_events,public.audit_runs to authenticated;

create table public.principles(id text primary key,title text not null,domain text not null,description text not null,active boolean not null default true);
create table public.principle_versions(id uuid primary key default gen_random_uuid(),principle_id text not null references public.principles on delete cascade,version int not null,operational_rule text not null,created_at timestamptz not null default now(),unique(principle_id,version));
create table public.audit_principle_links(id uuid primary key default gen_random_uuid(),conversation_audit_id uuid not null references public.conversation_audits on delete cascade,principle_id text not null references public.principles,evidence jsonb not null default '[]',application text not null);
create table public.conversation_strategy_versions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,thread_id text not null references public.email_threads on delete cascade,version int not null,suggestion jsonb not null,requires_human_approval boolean not null default true,approved_at timestamptz,created_at timestamptz not null default now(),unique(thread_id,version));
create table public.relationship_edges(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,from_type text not null,from_id text not null,to_type text not null,to_id text not null,edge_type text not null,provenance text not null check(provenance in('FACT','INFERENCE','UNKNOWN')),evidence jsonb not null default '[]',created_at timestamptz not null default now());
create table public.relationship_node_metadata(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,node_type text not null,node_id text not null,metadata jsonb not null default '{}',unique(user_id,node_type,node_id));
create table public.message_experiments(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,name text not null,hypothesis text not null,ethical_reviewed boolean not null default false,created_at timestamptz not null default now());
create table public.message_experiment_outcomes(id uuid primary key default gen_random_uuid(),experiment_id uuid not null references public.message_experiments on delete cascade,thread_id text not null references public.email_threads,outcome text not null,observed_at timestamptz not null,metadata jsonb not null default '{}');
create table public.design_audits(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,route text not null,status text not null,score int check(score between 0 and 100),created_at timestamptz not null default now());
create table public.design_audit_findings(id uuid primary key default gen_random_uuid(),design_audit_id uuid not null references public.design_audits on delete cascade,severity text not null,evidence text not null,principle_id text references public.principles,concrete_fix text not null,acceptance_criterion text not null);
create index idx_relationship_path on public.relationship_edges(user_id,from_type,from_id,to_type,to_id);create index idx_strategy_thread on public.conversation_strategy_versions(user_id,thread_id,version desc);create index idx_experiment_outcome on public.message_experiment_outcomes(experiment_id,outcome);
alter table public.principles enable row level security;alter table public.principle_versions enable row level security;alter table public.audit_principle_links enable row level security;alter table public.conversation_strategy_versions enable row level security;alter table public.relationship_edges enable row level security;alter table public.relationship_node_metadata enable row level security;alter table public.message_experiments enable row level security;alter table public.message_experiment_outcomes enable row level security;alter table public.design_audits enable row level security;alter table public.design_audit_findings enable row level security;
create policy principles_read on public.principles for select to authenticated using(true);create policy principle_versions_read on public.principle_versions for select to authenticated using(true);
create policy strategy_owner on public.conversation_strategy_versions for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy edge_owner on public.relationship_edges for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy node_owner on public.relationship_node_metadata for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy experiment_owner on public.message_experiments for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy design_audit_owner on public.design_audits for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
grant select on public.principles,public.principle_versions to authenticated;grant select,insert,update,delete on public.conversation_strategy_versions,public.relationship_edges,public.relationship_node_metadata,public.message_experiments,public.design_audits to authenticated;

create table public.sales_plans(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,name text not null,scenario text not null,assumptions jsonb not null,primary_metric text not null default 'QUALIFIED_EV_PER_HOUR',active boolean not null default true,created_at timestamptz not null default now());
create table public.forecast_versions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,sales_plan_id uuid not null references public.sales_plans on delete cascade,version int not null,assumptions jsonb not null,model_version text not null,created_at timestamptz not null default now(),unique(sales_plan_id,version));
create table public.forecast_points(id uuid primary key default gen_random_uuid(),forecast_version_id uuid not null references public.forecast_versions on delete cascade,horizon_days int not null check(horizon_days in(5,15,30,90,180,365,1095)),expected_accounts numeric not null,expected_qualified numeric not null,expected_proposals numeric not null,expected_wins numeric not null,expected_pipeline_value numeric not null,expected_recognized_revenue numeric not null,capacity_utilization numeric not null,unique(forecast_version_id,horizon_days));
create table public.account_targets(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,company_id uuid references public.companies on delete cascade,segment text not null,problem_hypothesis text,verified_signal text,positioning jsonb not null default '{}',status text not null,next_action text,next_action_at timestamptz,created_at timestamptz not null default now());
create table public.pipeline_stage_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,account_target_id uuid references public.account_targets on delete cascade,opportunity_id uuid references public.opportunities on delete cascade,from_stage text,to_stage text not null,reason text,evidence jsonb not null default '[]',occurred_at timestamptz not null default now());
create table public.client_engagements(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,company_id uuid not null references public.companies,onboarding_at timestamptz,status text not null,hourly_rate numeric,contracted_hours_week numeric,desired_outcome text not null,next_value_milestone text,next_value_at timestamptz,renewal_at timestamptz,ended_at timestamptz);
create table public.client_health_snapshots(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,client_engagement_id uuid not null references public.client_engagements on delete cascade,captured_at timestamptz not null default now(),outcome_progress int not null check(outcome_progress between 0 and 100),relationship_health int not null check(relationship_health between 0 and 100),delivery_health int not null check(delivery_health between 0 and 100),payment_health int not null check(payment_health between 0 and 100),risk_flags jsonb not null default '[]',next_action text not null,next_action_at timestamptz not null);
create table public.value_deliveries(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users on delete cascade,client_engagement_id uuid not null references public.client_engagements on delete cascade,delivered_at timestamptz not null,description text not null,evidence jsonb not null default '[]',client_outcome text,approved_by_client boolean not null default false);
create index idx_targets_next_action on public.account_targets(user_id,status,next_action_at);create index idx_stage_events on public.pipeline_stage_events(user_id,occurred_at desc);create index idx_client_health on public.client_health_snapshots(user_id,client_engagement_id,captured_at desc);create index idx_forecast_horizon on public.forecast_points(forecast_version_id,horizon_days);
alter table public.sales_plans enable row level security;alter table public.forecast_versions enable row level security;alter table public.forecast_points enable row level security;alter table public.account_targets enable row level security;alter table public.pipeline_stage_events enable row level security;alter table public.client_engagements enable row level security;alter table public.client_health_snapshots enable row level security;alter table public.value_deliveries enable row level security;
create policy sales_plan_owner on public.sales_plans for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy forecast_owner on public.forecast_versions for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy account_target_owner on public.account_targets for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy stage_event_owner on public.pipeline_stage_events for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy client_engagement_owner on public.client_engagements for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy client_health_owner on public.client_health_snapshots for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy value_delivery_owner on public.value_deliveries for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
grant select,insert,update,delete on public.sales_plans,public.forecast_versions,public.account_targets,public.pipeline_stage_events,public.client_engagements,public.client_health_snapshots,public.value_deliveries to authenticated;

-- Final deny-by-default must run after every table is created because local/cloud
-- default privileges may otherwise expose objects created after an earlier REVOKE.
revoke all privileges on all tables in schema public from anon,authenticated;
grant select on public.sources,public.principles,public.principle_versions to authenticated;
grant select,insert,update,delete on public.users,public.search_runs,public.companies,public.contacts,public.relationships,public.job_postings,public.opportunities,public.career_facts,public.cv_versions,public.applications,public.cover_letters,public.email_threads,public.followups,public.referrals,public.interviews,public.offers,public.revenues,public.bounty_programs,public.tasks,public.activity_events,public.audit_runs,public.conversation_strategy_versions,public.relationship_edges,public.relationship_node_metadata,public.message_experiments,public.design_audits,public.sales_plans,public.forecast_versions,public.account_targets,public.pipeline_stage_events,public.client_engagements,public.client_health_snapshots,public.value_deliveries to authenticated;
